const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const etoshaPan = ee.Geometry.Polygon(
    [[[14.88, -18.78],
      [14.88, -19.45],
      [17.07, -19.45],
      [17.07, -18.78],
      [14.88, -18.78]]], null, false);

  const dateJanStart = '2020-01-10';
  const dateJanEnd = '2020-01-20'; // Mid-January
  const dateAugStart = '2020-08-20';
  const dateAugEnd = '2020-08-30'; // Late August

  const S2_COLLECTION = 'COPERNICUS/S2_SR'; // Sentinel-2 L2A for surface reflectance

  // 2. Cloud Masking Function for Sentinel-2 SR
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to SR values (0-1)
  }

  // 3. MNDWI function for Sentinel-2 SR
  function calculateMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI'); // Green (B3), SWIR1 (B11)
    return image.addBands(mndwi);
  }

  // Function to get water area for a given period
  async function getWaterArea(startDate, endDate, periodName) {
    let collection = ee.ImageCollection(S2_COLLECTION)
      .filterBounds(etoshaPan)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Pre-filter for less cloudy images

    if (collection.size().getInfo() === 0) {
      console.log(`No Sentinel-2 images found for ${periodName}.`);
      return { area: null, status: 'C1' };
    }

    // Apply cloud mask and MNDWI
    collection = collection.map(maskS2clouds).map(calculateMNDWI);

    // Get a median composite to reduce noise
    const medianImage = collection.median();

    // Check if the median image is null or contains only masked pixels after processing
    // (A common issue with heavily masked images producing no data)
    const bandNames = medianImage.bandNames().getInfo();
    if (bandNames.length === 0) {
        console.log(`Median image for ${periodName} is empty after processing.`);
        return { area: null, status: 'C2' };
    }

    // Calculate valid pixels for the region
    const originalPixels = medianImage.select('B3').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: etoshaPan,
      scale: 30, // Sentinel-2 resolution
      maxPixels: 1e9
    }).get('B3').getInfo();

    if (originalPixels === 0 || originalPixels === null) {
      console.log(`No valid pixels remaining for ${periodName} after cloud masking.`);
      return { area: null, status: 'C2' };
    }

    // Threshold MNDWI to get water mask (MNDWI > 0)
    const waterMask = medianImage.select('MNDWI').gt(0).rename('water');

    // Calculate water area
    const waterArea = waterMask.multiply(ee.Image.pixelArea())
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: etoshaPan,
        scale: 30, // Sentinel-2 resolution
        maxPixels: 1e9
      }).get('water');

    const areaVal = waterArea.getInfo();

    if (areaVal === null || isNaN(areaVal)) {
      console.log(`Calculation failed for ${periodName}: ${areaVal}`);
      return { area: null, status: 'C3' };
    }

    return { area: areaVal / 1e6, originalPixels: originalPixels }; // Convert to km^2
  }

  // Process for January
  const janResult = await getWaterArea(dateJanStart, dateJanEnd, 'mid-January');
  if (janResult.status) {
    console.log(janResult.status);
    return;
  }
  const waterAreaJan = janResult.area;
  console.log(`Mid-January (2020) Water Extent: ${waterAreaJan.toFixed(2)} km^2 (Valid Pixels: ${janResult.originalPixels})`);

  // Process for August
  const augResult = await getWaterArea(dateAugStart, dateAugEnd, 'late August');
  if (augResult.status) {
    console.log(augResult.status);
    return;
  }
  const waterAreaAug = augResult.area;
  console.log(`Late August (2020) Water Extent: ${waterAreaAug.toFixed(2)} km^2 (Valid Pixels: ${augResult.originalPixels})`);

  // 5. Validation & Final Answer
  if (waterAreaJan === null || waterAreaAug === null) {
    console.log("C3"); // Should be caught by earlier checks, but as a safeguard
    return;
  }

  if (waterAreaAug < waterAreaJan) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
